using System;using System.Linq;using System.Collections.Generic;using System.Globalization;
public static class ProcessWatchAlerts {
 public static MonitorAlert[] Observe(WatchedProcess process,AssistantConfig cfg){var result=new List<MonitorAlert>();if(!cfg.ProcessAlerts){process.AlertStreaks.Clear();return result.ToArray();}var active=new HashSet<string>();foreach(string metric in new[]{"cpu","memory"})foreach(double point in ThresholdPoints.Effective(metric=="cpu"?cfg.ProcessCpuPoints:cfg.ProcessMemoryPoints,metric=="cpu"?cfg.CpuThreshold:cfg.MemoryThreshold,.01,metric=="cpu"?100:1000000)){string key=metric+":"+point.ToString(CultureInfo.InvariantCulture);active.Add(key);double value=metric=="cpu"?process.CpuPercent:process.MemoryMiB;int streak;process.AlertStreaks.TryGetValue(key,out streak);if(Double.IsNaN(value)||Double.IsInfinity(value)||value<point*.92)streak=0;else if(value<point){if(streak<3)streak=0;}else if(streak<3){streak++;if(streak==3)result.Add(new MonitorAlert{Key=key,Value=value,Threshold=point,Text=(metric=="cpu"?"CPU":"内存")+"持续超过 "+point.ToString("0.##")+(metric=="cpu"?"%":" MiB")+"，当前 "+value.ToString("F1")+(metric=="cpu"?"%":" MiB")+"。"});}process.AlertStreaks[key]=streak;}foreach(string key in process.AlertStreaks.Keys.Where(k=>!active.Contains(k)).ToArray())process.AlertStreaks.Remove(key);return result.ToArray();}
}
